/* ============================================
   TABS COMPONENT
   Horizontal tab navigation with underline
   ============================================ */

.ds-tabs {
  display: inline-flex;
  align-items: stretch;
  gap: 0;
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
}

/* ============================================
   FULL WIDTH
   ============================================ */

.ds-tabs--full-width {
  display: flex;
  width: 100%;
}

.ds-tabs--full-width .ds-tabs__tab {
  flex: 1;
}

/* ============================================
   TAB BUTTON
   ============================================ */

.ds-tabs__tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-200); /* 8px */
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  border: none;
  border-bottom: var(--border-050) solid transparent;
  margin-bottom: calc(var(--border-025) * -1); /* Overlap the container border */
  background: none;
  cursor: pointer;
  position: relative;

  /* Typography — paragraph em (medium weight) for clickable controls */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);

  transition: color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-tabs--compact .ds-tabs__tab {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-emphasis-size);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-tabs--compact .ds-tabs__icon {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   LABEL
   ============================================ */

.ds-tabs__label {
  color: var(--color-text-tertiary);
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   ICON
   ============================================ */

.ds-tabs__icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-secondary);
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   DEFAULT (inactive) TAB
   ============================================ */

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover .ds-tabs__label {
  color: var(--color-text-primary);
}

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover .ds-tabs__icon {
  color: var(--color-icon-primary);
}

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover {
  border-bottom-color: var(--color-bg-container-secondary);
}

/* ============================================
   ACTIVE TAB
   ============================================ */

.ds-tabs__tab--active {
  border-bottom-color: var(--color-action-primary-bg);
}

.ds-tabs__tab--active .ds-tabs__label {
  color: var(--color-text-primary);
}

.ds-tabs__tab--active .ds-tabs__icon {
  color: var(--color-action-primary-bg);
}

.ds-tabs__tab--active:not(.ds-tabs__tab--disabled):hover {
  border-bottom-color: var(--color-action-primary-bg);
}

/* ============================================
   FOCUS STATE
   ============================================ */

.ds-tabs__tab:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-200);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-tabs__tab--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

'use client';

import React from 'react';
import './Tabs.css';
import '../../fonts/material-symbols.css';

export interface Tab {
  /** Unique tab identifier */
  value: string;
  /** Display label */
  label: string;
  /** Optional icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Whether this tab is disabled */
  disabled?: boolean;
}

export interface TabsProps {
  /** Array of tab definitions */
  tabs: Tab[];
  /** Currently active tab value */
  activeTab: string;
  /** Callback when tab is selected */
  onTabChange?: (value: string) => void;
  /** Visual size */
  size?: 'default' | 'compact';
  /** Whether tabs fill the available width */
  fullWidth?: boolean;
  /** Additional CSS classes */
  className?: string;
  /** Accessible label for the tab list */
  ariaLabel?: string;
}

export const Tabs = ({
  tabs,
  activeTab,
  onTabChange,
  size = 'default',
  fullWidth = false,
  className = '',
  ariaLabel = 'Tabs',
}: TabsProps) => {
  const baseClass = 'ds-tabs';
  const sizeClass = `${baseClass}--${size}`;
  const fullWidthClass = fullWidth ? `${baseClass}--full-width` : '';

  const classes = [baseClass, sizeClass, fullWidthClass, className]
    .filter(Boolean)
    .join(' ');

  const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
    const enabledTabs = tabs.filter((t) => !t.disabled);
    const currentEnabledIndex = enabledTabs.findIndex((t) => t.value === tabs[index].value);

    let targetTab: Tab | undefined;

    switch (e.key) {
      case 'ArrowRight':
        e.preventDefault();
        targetTab = enabledTabs[(currentEnabledIndex + 1) % enabledTabs.length];
        break;
      case 'ArrowLeft':
        e.preventDefault();
        targetTab = enabledTabs[(currentEnabledIndex - 1 + enabledTabs.length) % enabledTabs.length];
        break;
      case 'Home':
        e.preventDefault();
        targetTab = enabledTabs[0];
        break;
      case 'End':
        e.preventDefault();
        targetTab = enabledTabs[enabledTabs.length - 1];
        break;
    }

    if (targetTab && onTabChange) {
      onTabChange(targetTab.value);
      // Focus the new tab button
      const tabList = (e.target as HTMLElement).parentElement;
      const targetEl = tabList?.querySelector(`[data-tab-value="${targetTab.value}"]`) as HTMLElement;
      targetEl?.focus();
    }
  };

  return (
    <div className={classes} role="tablist" aria-label={ariaLabel}>
      {tabs.map((tab, index) => {
        const isActive = tab.value === activeTab;
        const tabClass = [
          `${baseClass}__tab`,
          isActive ? `${baseClass}__tab--active` : '',
          tab.disabled ? `${baseClass}__tab--disabled` : '',
        ]
          .filter(Boolean)
          .join(' ');

        return (
          <button
            key={tab.value}
            type="button"
            className={tabClass}
            role="tab"
            aria-selected={isActive}
            aria-disabled={tab.disabled}
            tabIndex={isActive ? 0 : -1}
            data-tab-value={tab.value}
            onClick={() => !tab.disabled && onTabChange?.(tab.value)}
            onKeyDown={(e) => handleKeyDown(e, index)}
          >
            {tab.icon &&
              (typeof tab.icon === 'string' ? (
                <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
                  {tab.icon}
                </span>
              ) : (
                <span className={`${baseClass}__icon`} aria-hidden="true">
                  {tab.icon}
                </span>
              ))}
            <span className={`${baseClass}__label`}>{tab.label}</span>
          </button>
        );
      })}
    </div>
  );
};
